#[inline]
fn destack_gpu_device_pop_error_scope_vm_replay(
    runtime: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    device: resource::GpuDeviceHandle,
    timeoutns: u64,
) -> RuntimeResult<vm::Value> {
    let result = runtime.replay().run_binding_with_context_policy(
        GPU_DEVICE_POP_ERROR_SCOPE,
        runtime.replay_payload_for(GPU_DEVICE_POP_ERROR_SCOPE)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_gpu_device_pop_error_scope(runtime, context, device, timeoutns)
            }
            RuntimeWorld::Simulation => platform_simulation_vm::destack_gpu_device_pop_error_scope(
                runtime, context, device, timeoutns,
            ),
        },
        |context, result| {
            let _ = &context;
            if let Ok(value) = result {
                let result_value: GpuCapturedErrorVm = value.clone();
                let result_recorded_message = if let Some(value) = result_value.message {
                    let result_recorded_message_inner = {
                        let result_recorded_message_inner_ref = context
                            .string_ref(value)
                            .map_err(|error| RuntimeError::from(error).boxed())?;
                        result_recorded_message_inner_ref.as_str().to_string()
                    };
                    Some(result_recorded_message_inner)
                } else {
                    None
                };
                let result_recorded_backend_code = if let Some(value) = result_value.backend_code {
                    let result_recorded_backend_code_inner = value;
                    Some(result_recorded_backend_code_inner)
                } else {
                    None
                };
                let result_recorded = GpuCapturedErrorReplayRecord {
                    message: result_recorded_message,
                    backend_code: result_recorded_backend_code,
                };
                let payload = GpuDevicePopErrorScopeReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    GpuDevicePopErrorScopeReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let _ = &context;
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result_message = if let Some(value) = value.message {
                        let vm_result_message_inner_value = context.intern_string(value.as_str());
                        let vm_result_message_inner =
                            vm::StringHandle::new(vm_result_message_inner_value);
                        Some(vm_result_message_inner)
                    } else {
                        None
                    };
                    let vm_result_backend_code = if let Some(value) = value.backend_code {
                        let vm_result_backend_code_inner = value;
                        Some(vm_result_backend_code_inner)
                    } else {
                        None
                    };
                    let vm_result = GpuCapturedErrorVm {
                        message: vm_result_message,
                        backend_code: vm_result_backend_code,
                    };
                    Ok(vm_result)
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    );
    let result = encode_destack_gpu_device_pop_error_scope_result(context, result)?;
    Ok(result)
}

